import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.PriorityQueue;

class Completed {

    public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {

        List<List<Integer>> result = new ArrayList<>();

        if (nums1.length == 0 || nums2.length == 0 || k == 0) {
            return result;
        }

        PriorityQueue<int[]> minHeap = new PriorityQueue<>(
            (a, b) -> Integer.compare(a[0] + a[1], b[0] + b[1])
        );

        for (int i = 0; i < nums1.length && i < k; i++) {
            minHeap.offer(new int[]{nums1[i], nums2[0], 0});
        }

        while (k-- > 0 && !minHeap.isEmpty()) {

            int[] current = minHeap.poll();
            result.add(Arrays.asList(current[0], current[1]));

            int indexInNums2 = current[2];

            if (indexInNums2 + 1 < nums2.length) {
                minHeap.offer(new int[]{current[0], nums2[indexInNums2 + 1], indexInNums2 + 1});
            }
        }

        return result;
    }
}

